  ('119e682c-eaa7-542a-90d4-e31fa79b00d5', 'OBL-0205', '1fc86270-74bd-596e-a169-8f9f0fa886a6', 'Monthly Service Report by 5th business day', 'reporting', '<=', 5, 'business day of month', 'monthly', '≤ BD5 monthly', 'The report arrives by email only; there is no timestamped record of when it was received.', 'Service Provider shall deliver the Monthly Service Report no later than the fifth (5th) Business Day of the following month.', 0.88, 'manual', 'confirmed'),
  ('e7359f47-7a34-5ed1-a96a-d9c86b3a4c22', 'OBL-0206', 'e1bde193-1b82-5456-873c-acf5b6e61b1d', 'Invoice accuracy ≥ 99.5% per quarter', 'performance_target', '>=', 99.5, '%', 'quarterly', '≥ 99.5% / quarter', null, 'Service Provider shall maintain invoice accuracy of at least 99.5% per calendar quarter.', 0.72, 'manual', 'confirmed'),
  ('b3bbb8bd-b538-5d22-a9f6-61517b5b4836', 'OBL-0207', '7ee722ce-0adf-5d81-8620-37e0424e2e7e', '40 hours of training before agents go live', 'performance_target', '>=', 40, 'hours', 'per event', '≥ 40 h per agent', 'Training hours live in Service Provider''s learning system; Customer receives no data.', 'Service Provider shall ensure each agent completes no fewer than forty (40) hours of Customer-approved training before handling live Customer interactions.', 0.84, 'manual', 'confirmed'),
  ('2f9b69f9-b03c-53a3-9e93-0fe29b01a36d', 'OBL-0301', 'f99af5ec-56bb-51ff-a290-cf69e0c2e0b0', 'Answer data subject access requests within 30 days', 'regulatory', '<=', 30, 'days', 'per event', '≤ 30 days per request', null, 'The Company shall respond to verified data subject access requests within thirty (30) calendar days of receipt.', 0.94, 'manual', 'confirmed'),
  ('90380394-b25f-5134-9012-077fd5b5c5a9', 'OBL-0302', '1f085407-37a1-5a0a-81b6-04e87eda140a', 'Notify the regulator of a breach within 72 hours', 'regulatory', '<=', 72, 'hours', 'per event', '≤ 72 h per breach', null, 'Where a personal data breach is likely to result in a risk to individuals, the Company shall notify the supervisory authority without undue delay and, where feasible, not later than 72 hours after becoming aware of it.', 0.9, 'manual', 'confirmed'),
  ('74eda676-24ee-585b-9211-b79d3eebd70b', 'OBL-0303', 'f11a83f9-e4ab-5752-bf27-a9d9f57bbff9', 'Vendor risk assessment before data access', 'regulatory', '=', 100, '%', 'per event', 'Assessment before access (100%)', null, 'A privacy and security risk assessment shall be completed and approved before any third party is granted access to Personal Data.', 0.76, 'manual', 'confirmed'),
  ('29ded04e-693c-5b85-9b68-1f13da3c3182', 'OBL-0304', '1f1d2378-666a-5776-a578-f6b69f8213ef', 'Quarterly access reviews for personal-data systems', 'regulatory', '=', 100, '% of systems', 'quarterly', '100% of systems / quarter', null, 'System owners shall complete a user access review for every system that stores Personal Data at least once each calendar quarter.', 0.8, 'manual', 'confirmed'),
  ('2012575d-3746-53b1-bf37-8581e7d2316a', 'OBL-0305', '66d500f4-72fd-55d5-806a-decba1a1cd1c', 'Privacy training completion ≥ 95% annually', 'regulatory', '>=', 95, '%', 'annually', '≥ 95% / year', null, 'All workforce members shall complete privacy awareness training annually, and the Company shall maintain a completion rate of at least ninety-five percent (95%).', 0.93, 'manual', 'confirmed'),
  ('4eeef15d-62c5-5d3f-ade8-2ad7a51ba47f', 'OBL-0306', '131f679d-2d24-54e5-b925-d7362c792b55', 'Delete customer records within 90 days of retention expiry', 'regulatory', '<=', 90, 'days', 'per event', '≤ 90 days after expiry', 'No system reports records held past their retention date.', 'Customer records shall be deleted or anonymized within ninety (90) days after the applicable retention period expires.', 0.83, 'manual', 'confirmed');

