  ('faac3f45-67d4-5562-b016-9894a379d79c', '90380394-b25f-5134-9012-077fd5b5c5a9', '49309727-da6c-5c6c-9431-85033a01a92c', 'tracked', null, 0.9, 'confirmed'),
  ('697a29f4-25bc-512a-b1f9-26d937b35c6c', '74eda676-24ee-585b-9211-b79d3eebd70b', '68a998dc-d0ca-5b77-b60c-9ce3f951339f', 'partial', 'Completion is tracked, but not compared with the date access was granted.', 0.76, 'proposed'),
